define("quizaccess_presencial/start_request",[],function(){"use strict";const init=function(requestUrl){document.addEventListener("click",function(event){const target=event.target instanceof Element?event.target:null;const button=target?target.closest('.quizstartbuttondiv button[type="submit"]'):null;if(!button||button.closest(".quizsecuremoderequired")||document.querySelector("#mod_quiz_preflight_form")){return;}const form=button.closest("form");if(!form){return;}event.preventDefault();event.stopImmediatePropagation();form.action=requestUrl;form.submit();},true);};const continue_preflight=function(){const form=document.querySelector("#mod_quiz_preflight_form");if(!form){return;}const nativeControls=Array.from(form.querySelectorAll("input, select, textarea")).filter(function(field){return !["hidden","submit","button","reset"].includes(field.type);});if(nativeControls.length){return;}const submit=form.querySelector('[name="submitbutton"]');if(submit){submit.click();}};return{init:init,continue_preflight:continue_preflight};});
